public static int toNumber(Queue<Integer> q) {
    int num = 0;
    int place = 1;   // 1, 10, 100...
    while (!q.isEmpty()) {
        num = num + q.remove() * place;
        place = place * 10;
    }
    return num;
}

public static int bigNumber(Node<Queue<Integer>> lst) {
    int max = toNumber(lst.getValue());
    Node<Queue<Integer>> p = lst.getNext();
    while (p != null) {
        int n = toNumber(p.getValue());
        if (n > max) {
            max = n;
        }
        p = p.getNext();
    }
    return max;
}

