public static int ToNumber(Queue<int> q)
{
    int num = 0;
    int place = 1;   // 1, 10, 100...
    while (!q.IsEmpty())
    {
        num = num + q.Remove() * place;
        place = place * 10;
    }
    return num;
}

public static int BigNumber(Node<Queue<int>> lst)
{
    int max = ToNumber(lst.GetValue());
    Node<Queue<int>> p = lst.GetNext();
    while (p != null)
    {
        int n = ToNumber(p.GetValue());
        if (n > max)
        {
            max = n;
        }
        p = p.GetNext();
    }
    return max;
}

